SELECT s1.`c0` AS `id`, s1.`c1` AS `__weight` FROM (SELECT s2.`c2` AS `c0`, s2.`c1` AS `c1` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c0` AS `c2` FROM (SELECT s4.`c4` AS `c0`, s4.`c3` AS `c1` FROM (SELECT s5.`c0` AS `c0`, s5.`c1` AS `c1`, s5.`c2` AS `c2`, s5.`c3` AS `c3`, s5.`c0` AS `c4` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2`, `__weight` AS `c3` FROM `orders$delta`) AS s5) AS s4) AS s3) AS s2) AS s1
